application.css:
* { box-sizing: border-box; }

:root {
  --ink: #20232d;
  --muted: #7f8494;
  --line: #e8e9ef;
  --purple: #6d5dfc;
  --purple-dark: #5747e8;
  --soft-purple: #f0efff;
  --card: #ffffff;
}

body {
  margin: 0;
  min-height: 100vh;
  background: linear-gradient(135deg, #f5f3ff 0%, #eef8ff 100%);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.app-shell { width: min(100% - 32px, 650px); margin: 0 auto; padding: 64px 0 30px; }
.todo-card { background: var(--card); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; box-shadow: 0 22px 60px rgba(62, 56, 126, .13); padding: 38px; }
.app-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 30px; }
.eyebrow { color: var(--purple); font-size: 11px; font-weight: 800; letter-spacing: .15em; margin: 0 0 10px; }
h1 { font-size: clamp(2rem, 6vw, 2.7rem); letter-spacing: -.06em; margin: 0; line-height: 1.05; }
.subtitle { color: var(--muted); margin: 12px 0 0; font-size: 14px; }
.header-mark { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 17px; background: var(--soft-purple); color: var(--purple); font-size: 25px; font-weight: 800; transform: rotate(8deg); }
.task-form { display: flex; gap: 10px; margin-bottom: 34px; }
.task-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; color: var(--ink); font: inherit; outline: none; background: #fcfcfe; transition: border .2s, box-shadow .2s; }
.task-form input:focus { border-color: var(--purple); box-shadow: 0 0 0 4px rgba(109,93,252,.12); }
.task-form button { border: 0; border-radius: 12px; padding: 0 18px; background: var(--purple); color: white; font: 700 14px inherit; cursor: pointer; box-shadow: 0 7px 14px rgba(109,93,252,.2); transition: background .2s, transform .2s; }
.task-form button:hover { background: var(--purple-dark); transform: translateY(-1px); }
.task-form button span { font-size: 20px; vertical-align: -1px; margin-left: 5px; }
.list-heading { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.list-heading h2 { font-size: 16px; margin: 0; }
.list-heading p { color: var(--muted); font-size: 13px; margin: 0; }
.list-heading p span:first-child { color: var(--purple); font-weight: 800; }
.task-list { display: grid; gap: 9px; }
.task-item { display: flex; align-items: center; gap: 12px; border: 1px solid var(--line); border-radius: 13px; padding: 13px 13px 13px 15px; animation: appear .25s ease-out; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
.task-toggle { flex: 0 0 auto; width: 21px; height: 21px; border: 2px solid #c9cbd5; border-radius: 7px; background: white; color: white; cursor: pointer; font-size: 13px; line-height: 16px; padding: 0; }
.task-toggle:hover { border-color: var(--purple); }
.task-item[data-completed="true"] .task-toggle { border-color: var(--purple); background: var(--purple); }
.task-text { flex: 1; min-width: 0; overflow-wrap: anywhere; font-size: 14px; }
.task-item[data-completed="true"] .task-text { color: #a0a3ae; text-decoration: line-through; }
.delete-button { border: 0; background: transparent; color: #b3b6c1; cursor: pointer; font-size: 20px; padding: 4px 5px; line-height: 1; border-radius: 6px; }
.delete-button:hover { color: #ec6b78; background: #fff1f2; }
.empty-state { display: flex; flex-direction: column; align-items: center; gap: 5px; color: var(--muted); padding: 32px 0 12px; font-size: 13px; }
.empty-state strong { color: var(--ink); font-size: 14px; }
.empty-icon { display: grid; place-items: center; width: 43px; height: 43px; margin-bottom: 5px; border-radius: 50%; color: var(--purple); background: var(--soft-purple); font-size: 21px; }
.footer-note { color: #9b9eae; text-align: center; font-size: 12px; margin: 18px 0 0; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 500px) { .app-shell { padding-top: 25px; } .todo-card { padding: 25px 20px; border-radius: 19px; } .task-form { flex-direction: column; } .task-form button { height: 46px; } }

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.querySelector('[data-testid="task-input"]');
  const list = document.querySelector('[data-testid="task-list"]');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const label = document.getElementById('count-label');
  const empty = document.getElementById('empty-state');
  let tasks = [];

  function render() {
    list.replaceChildren();
    tasks.forEach(task => {
      const item = document.createElement('article');
      item.className = 'task-item';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'task-toggle';
      toggle.dataset.testid = 'task-complete';
      toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      toggle.setAttribute('aria-pressed', String(task.completed));
      toggle.textContent = task.completed ? '✓' : '';
      toggle.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', 'Delete task');
      remove.textContent = '×';
      remove.addEventListener('click', () => {
        tasks = tasks.filter(candidate => candidate.id !== task.id);
        render();
      });

      item.append(toggle, text, remove);
      list.appendChild(item);
    });
    const remaining = tasks.filter(task => !task.completed).length;
    count.textContent = remaining;
    label.textContent = remaining === 1 ? 'task remaining' : 'tasks remaining';
    empty.hidden = tasks.length !== 0;
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }
    tasks.push({ id: Date.now() + Math.random(), text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
})();

